INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_ADJECTIVE','Circus');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_ATTACKED_1','You mistake kindness for an unguarded gate. Our people will stand together.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_AURELIO_HEADING_1','The Lantern Keeper Who Became a Leader');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_AURELIO_LIVED','The Age of Traveling Wonders');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_AURELIO_NAME','Ringmaster Aurelio');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_AURELIO_SUBTITLE','Host of the Grand Pavilion');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_AURELIO_TEXT_1','Aurelio first traveled with the circus as a lantern keeper. He learned the names of every performer, the carrying capacity of every wagon and the art of turning a delayed opening into a memorable welcome. Chosen to mediate between rival companies, he became the first Ringmaster of the Grand Pavilion.[NEWLINE][NEWLINE]His elaborate crimson coat, black top hat and golden gloves are ceremonial tools of an exacting host. Behind his theatrical greetings lies a curious and commercially minded organizer. He funds schools beside stages and welcomes foreign merchants, believing that a prosperous neighbor makes a better audience. When threatened, his warmth becomes a public promise to protect his people.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_AURELIO_TITLES_1','Ringmaster Aurelio');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_CITY_1','Grand Pavilion');
