INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_CITY_7','Ringmaster''s Rest');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_CITY_8','Starlight Fair');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_CITY_9','Tumbler''s Crossing');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_CIV','The Wandering Circus');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_CIV5_HEADING_1','A Civilization Beneath the Canopy');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_CIV5_TEXT_1','The Wandering Circus is an original fictional civilization of performers, acrobats, musicians, stagehands and merchants. It began as a loose alliance of caravans that shared shelter and water at a crossroads. When winter held them there, their temporary pavilion became a school, a market and eventually a capital.[NEWLINE][NEWLINE]The Grand Pavilion remains a meeting place for travelers. Other settlements grew beside fairgrounds and river crossings, linked by roads built by the same crews who raised their stages. A festival belongs to its host city: when one city rests, another may be preparing its opening night.[NEWLINE][NEWLINE]Their history is a story of patient labor behind public delight. The roads must be repaired, the accounts balanced and the fields tended before a curtain can rise. Their people find dignity in that preparation and in the joy it makes possible.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_CIV_PEDIA','The Wandering Circus is an original fictional civilization of performers, acrobats, musicians, stagehands and merchants. It began as a loose alliance of caravans that shared shelter and water at a crossroads. When winter held them there, their temporary pavilion became a school, a market and eventually a capital.[NEWLINE][NEWLINE]The Grand Pavilion remains a meeting place for travelers. Other settlements grew beside fairgrounds and river crossings, linked by roads built by the same crews who raised their stages. A festival belongs to its host city: when one city rests, another may be preparing its opening night.[NEWLINE][NEWLINE]Their history is a story of patient labor behind public delight. The roads must be repaired, the accounts balanced and the fields tended before a curtain can rise. Their people find dignity in that preparation and in the joy it makes possible.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_DAWN','Magnificent Ringmaster Aurelio, the world awaits your greatest performance![NEWLINE][NEWLINE]Throughout history, kings have raised armies, emperors have constructed monuments, and scholars have sought the mysteries of existence.[NEWLINE][NEWLINE]But your people have discovered something equally powerful.[NEWLINE][NEWLINE]Joy.[NEWLINE][NEWLINE]Your traveling performers have crossed mountains, deserts and oceans, bringing laughter to those who have forgotten how to smile.[NEWLINE][NEWLINE]Now, the greatest stage of all awaits you.[NEWLINE][NEWLINE]Raise your tents. Gather your performers. Let every city hear the sound of celebration.[NEWLINE][NEWLINE]Will your civilization become the greatest spectacle the world has ever witnessed?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_DEFEAT_1','The lights grow dim... the audience departs... but somewhere, someday, the show will begin again.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_DUMMY','Grand Festival');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_DUMMY_HELP','Automatically maintained circus state. Cannot be built, purchased, sold or transferred.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_FRIENDLY_1','A familiar face! Come in, my friend. The finest seat in the pavilion is yours.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_GREETING_1','Welcome, welcome! A thousand greetings to our distinguished guest! Tell me, have you come for diplomacy, or would you prefer front-row seats?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_HOSTILE_1','You arrive to a rather quiet audience today. Speak plainly; our patience has limits.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_LEADER','Ringmaster Aurelio');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_LEADER_PEDIA','Aurelio first traveled with the circus as a lantern keeper. He learned the names of every performer, the carrying capacity of every wagon and the art of turning a delayed opening into a memorable welcome. Chosen to mediate between rival companies, he became the first Ringmaster of the Grand Pavilion.[NEWLINE][NEWLINE]His elaborate crimson coat, black top hat and golden gloves are ceremonial tools of an exacting host. Behind his theatrical greetings lies a curious and commercially minded organizer. He funds schools beside stages and welcomes foreign merchants, believing that a prosperous neighbor makes a better audience. When threatened, his warmth becomes a public promise to protect his people.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_NEUTRAL_1','The curtain is raised, and I am listening. What business brings you to our stage?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_OFFICE','Ticket Office');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_OFFICE_HELP','Replaces Market, retaining all its normal Community Patch benefits. Adds +1 [ICON_CULTURE] Culture permanently. During this city''s Grand Festival only, adds +2 flat [ICON_PRODUCTION] Production. This bonus never stacks with additional Carnival Crews.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_OFFICE_PEDIA','At the Ticket Office, the price of admission becomes a promise of wonder. Clerks arrange seating, merchants rent stalls and apprentices learn to keep accounts beside playbills. These small institutions preserve all the commercial functions of a Market. During a Grand Festival their coordinated deliveries also support the city''s workshops.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_OFFICE_STRATEGY','Raise Ticket Offices in cities that regularly welcome Carnival Crews. Their Market benefits and extra Culture are permanent; their additional Production lasts only while the local festival is active. Building an Office during a festival enables its Production for the remaining festival.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_PEACE_1','Let the drums fall silent and the lanterns shine again. There is room beneath our canopy for peace.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_PEACE_OFFER_1','We have both given war its dreadful encore. Shall we close this act and begin a kinder one?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SHORT','The Wandering Circus');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_1','Velvet Whisper');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_10','Last Bow');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_2','False Bottom');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_3','Quiet Encore');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_4','Silver Wire');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_5','Hidden Lantern');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_6','Painted Smile');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_7','Midnight Ticket');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_8','Scarlet Ribbon');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_SPY_9','Vanishing Act');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_STRATEGY','Pursue Culture through local Grand Festivals and permanent Ticket Office Culture, with Science as a secondary path supported by a healthy economy. Rotate Carnival Crews between infrastructure work and performances. Each city has its own three-turn festival and twelve-turn interval between starts; a stationed Crew automatically prepares the next eligible show. Growth and additional cities can support more simultaneous festivals, but each stationed Crew is time away from improvements.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_TRADE_1','A fair exchange deserves applause. Let us give our merchants something to celebrate.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_TRAIT','The Show Must Go On');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_TRAIT_HELP','A Carnival Crew ending its turn in your city can begin a Grand Festival at the start of your next turn. Each city gains +3 [ICON_CULTURE] Culture and +2 [ICON_GOLD] Gold for exactly 3 owner-turns. A city may begin another festival 12 owner-turns after its previous start. Crews are not consumed; multiple Crews do not stack.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_UNIT','Carnival Crew');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_UNIT_HELP','Replaces Worker, retaining all its normal Community Patch properties and build actions. +1 [ICON_MOVES] Movement compared with the active Worker. End a turn in one of your cities to prepare a Grand Festival for your next turn, if that city is eligible. The Crew is not consumed and may leave after activation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_UNIT_PEDIA','Stagehands build roads as readily as stages. The Carnival Crew carry tools, canvas, lanterns and instruments between settlements, repairing bridges in the morning and raising a pavilion at dusk. They are civilian Workers with the active Community Patch construction rules and a little more movement. Their performances require a city, not a special build action. The standard Worker model represents them on the map.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_UNIT_STRATEGY','Balance improvement work against local performances. Move into a city before ending your turn; passing through it is insufficient. Once its festival has begun, return to the fields or travel to another city. Work Rate remains the normal Worker rate.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_WCIRCUS_WAR_1','Ladies and gentlemen! For our next spectacular performance... THE FALL OF AN EMPIRE!');
